import pytest

from chunker import chunk


def test_chunk_sizes():
    assert chunk("abcdef", 2) == ["ab", "cd", "ef"]


def test_every_piece_within_size():
    for piece in chunk("abcdef", 3):
        assert len(piece) <= 3


def test_negative_size_rejected():
    with pytest.raises(ValueError):
        chunk("abc", 0)

