from collector import record, record_many


def test_single_call_returns_only_that_event():
    assert record("a") == ["a"]


def test_second_call_starts_empty():
    assert record("first") == ["first"]
    assert record("second") == ["second"], "第二次调用看到了上一次的事件"


def test_record_many_starts_empty():
    assert record_many(["x"]) == ["x"]
    assert record_many(["y"]) == ["y"], "第二次调用看到了上一次的事件"


def test_explicit_history_is_extended():
    history = ["x"]
    assert record("y", history) == ["x", "y"]
    assert history == ["x", "y"]

