"""读取配置。"""

from __future__ import annotations


class ConfigError(Exception):
    """配置相关的错误。"""


def get(config: dict[str, str], key: str, default: str | None = None) -> str:
    """取配置项；缺失且没有默认值时抛 ConfigError，并指出缺的是哪个键。"""
    if key not in config:
        if default is not None:
            return default
        raise KeyError(f"缺少配置项: {key}")
    return config[key]

files.tests/test_config.py:
import pytest

from config import ConfigError, get


def test_missing_without_default_raises_config_error():
    with pytest.raises(ConfigError) as excinfo:
        get({}, "timeout")

    assert "timeout" in str(excinfo.value)


def test_default_is_returned():
    assert get({}, "timeout", "30") == "30"


def test_present_value_is_returned():
    assert get({"timeout": "10"}, "timeout") == "10"

