"""按前缀过滤配置项。"""

from __future__ import annotations


def drop_prefix(config: dict[str, str], prefix: str) -> dict[str, str]:
    """返回去掉指定前缀键之后的新字典（不修改入参）。"""
    for key in config:
        if key.startswith(prefix):
            del config[key]
    return config

files.tests/test_filters.py:
from filters import drop_prefix


def test_removes_two_matching_keys():
    assert drop_prefix({"a_1": "x", "a_2": "z", "b": "y"}, "a_") == {"b": "y"}


def test_does_not_mutate_input():
    original = {"a_1": "x", "a_2": "z", "b": "y"}
    snapshot = dict(original)

    drop_prefix(original, "a_")

    assert original == snapshot, "入参不应被修改"


def test_no_match_returns_same_content():
    assert drop_prefix({"b": "y"}, "a_") == {"b": "y"}

