from ranking import top_n


def test_top_two_by_score():
    assert top_n([("a", 1), ("b", 3), ("c", 2)], 2) == ["b", "c"]


def test_single_highest():
    assert top_n([("low", 1), ("high", 9)], 1) == ["high"]


def test_zero_returns_empty():
    assert top_n([("a", 1)], 0) == []


def test_negative_returns_empty():
    assert top_n([("a", 1)], -3) == []


def test_n_larger_than_input():
    assert top_n([("a", 1), ("b", 2)], 5) == ["b", "a"]

