import pytest

from parser import parse_line


def test_parses_simple_pair():
    assert parse_line("a=1") == ("a", "1")


def test_empty_value_is_allowed():
    assert parse_line("a=") == ("a", "")


def test_value_may_contain_equals():
    assert parse_line("a=b=c") == ("a", "b=c")


def test_missing_equals_raises_value_error():
    with pytest.raises(ValueError):
        parse_line("a1")


def test_comment_and_blank_return_none():
    assert parse_line("# note") is None
    assert parse_line("   ") is None
